4320	// Merge a freshly-fetched snapshot with append records that arrived during the
4321	// fetch. The server's snapshot may have been built before a live-appended
4322	// record was cached, so any live append not already present in the snapshot is
4323	// preserved by appending it; appends already in the snapshot are dropped.
4324	function mergeSnapshotWithLiveAppends(snapshot, liveAppends) {
4325	  if (!liveAppends.length) return snapshot;
4326	  const seen = new Set(snapshot.map(recordKey));
4327	  const extra = liveAppends.filter((r) => !seen.has(recordKey(r)));
4328	  return extra.length ? snapshot.concat(extra) : snapshot;
4329	}
4330	
4331	// Filter incoming append records against an existing array, returning only
4332	// those whose recordKey is not already present. This covers the symmetric
4333	// race direction that mergeSnapshotWithLiveAppends cannot: the HTTP snapshot
4334	// lands AFTER the server cache write but BEFORE the WS broadcast, so the
4335	// snapshot already contains the batch; when the same batch arrives as a
4336	// `history_data` append moments later, blindly concating would duplicate
4337	// every record. Deduping here prevents that. Partial / stream_progress
4338	// records naturally have a different recordKey as their content accumulates,
4339	// so they are never incorrectly filtered out.
4340	function dedupeAppendRecords(existing, incoming) {
4341	  if (!incoming.length || !existing.length) return incoming;
4342	  const seen = new Set(existing.map(recordKey));
4343	  return incoming.filter((r) => !seen.has(recordKey(r)));
4344	}
