4348	// serve an incremental delta. With no progress (first open / after an
4349	// invalidation) the bare URL is returned, so the request is an unconditional
4350	// full snapshot — the first-open behaviour is unchanged. The token is encoded
4351	// via URLSearchParams so a base64url token (`-` / `_` / `=`) is transmitted
4352	// safely. Shared by both the running-flow and history-detail reconnect loaders.
4353	function historySnapshotUrl(flowId, progress) {
4354	  const base = `/api/history/${encodeURIComponent(flowId)}`;
4355	  if (!progress) return base;
4356	  const params = new URLSearchParams();
4357	  params.set("after", progress);
4358	  return `${base}?${params.toString()}`;
4359	}
