2657	  const records = Array.isArray(msg.records) ? msg.records : [];
2658	  const append = msg.mode === "append";
2659	
2660	  // -- history view consumer --
2661	  if (isHistoryOpen() && state.selectedHistoryId === msg.flow_id) {
2662	    // Capture the reader's position BEFORE re-rendering: an append grows
2663	    // scrollHeight, so "near bottom" must be measured against the old layout.
2664	    const stick = !append || isNearBottom(historyScrollContainer());
2665	    if (append) {
2666	      const fresh = dedupeAppendRecords(state.historyRecords, records);
2667	      if (fresh.length) {
2668	        state.historyRecords = state.historyRecords.concat(fresh);
2669	        renderHistoryRecords(msg.flow_id, state.historyRecords, append);
2670	        refreshHistoryStickyHeader();
2671	        if (stick) scrollHistoryToBottom();
2672	      }
2673	      // else: all duplicates — skip state update and render entirely
2674	    } else {
2675	      state.historyEpoch += 1;
2676	      state.historyRecords = records;
2677	      // A full push replaces the cached bundle server-side (a new generation),
2678	      // so any progress token we held no longer pins it — drop it so the next
2679	      // reconnect re-fetch falls back to a full load rather than echoing a
2680	      // stale delta cursor.
2681	      state.historyProgress = null;
2682	      renderHistoryRecords(msg.flow_id, state.historyRecords, append);
2683	      refreshHistoryStickyHeader();
2684	      if (stick) scrollHistoryToBottom();
2685	    }
2686	  }
2687	
2688	  // -- running-flow view consumer --
2689	  if (state.selectedFlowId === msg.flow_id) {
2690	    const stick = !append || isNearBottom($("flow-conversation"));
2691	    let merged;
2692	    if (append) {
2693	      const fresh = dedupeAppendRecords(state.flowConversationRecords, records);
2694	      if (!fresh.length) return;            // all duplicates — skip entirely
2695	      merged = state.flowConversationRecords.concat(fresh);
2696	    } else {
2697	      state.flowConversationEpoch += 1;
2698	      merged = records;
2699	      // Full push = new server bundle generation; the held delta cursor is now
2700	      // stale, so invalidate it (mirrors the history-view branch above).
2701	      state.flowConversationProgress = null;
2702	    }
2703	    // When the daemon's authoritative user record lands, drop the matching
2704	    // optimistic local echo so the reply is shown once. A mid-list removal
2705	    // shifts indices, so the incremental-append render (which only re-reads the
2706	    // tail) can no longer be trusted — force a full rebuild in that case.
2707	    const reconciled = reconcileLocalEchoes(merged);
2708	    const echoRemoved = reconciled !== merged;
2709	    state.flowConversationRecords = reconciled;
2710	    renderConversation(
